-- Demo seed, four companies — PART 3/4: billing (warptalk_billing). GENERATED by generate.py.
-- A live subscription per workspace on the `enterprise` plan, the plan the main demo workspace
-- runs on (no longer for sale, still honoured). Without it WT-515's paywall blocks meetings.
-- The entitlement snapshot is NOT written here: EntitlementReconcileWorker republishes it from
-- these rows within its interval (hourly). Never hand-write workspace_entitlement_snapshots.
\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE demo_plan AS
SELECT id FROM subscription.plans WHERE slug = 'enterprise' AND deleted_at IS NULL LIMIT 1;
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM demo_plan) THEN RAISE EXCEPTION 'No enterprise plan'; END IF;
END $$;

INSERT INTO subscription.subscriptions (
    id, user_id, workspace_id, plan_id, status, credits_remaining, credits_used_this_cycle,
