    service_state, owner_email_domain, billing_contact_email, created_at, created_by, updated_at, updated_by
)
SELECT '019f2b00-0de0-7000-9300-0000000000b1', '019f2b00-0de0-7000-9300-000000000101', '019f2b00-0de0-7000-9300-0000000000a1', p.id, 'active', 1400000, 0, 0,
       NOW() - INTERVAL '1 day', NOW() + INTERVAL '30 days', true, true, 'healthy',
       'lumoralogistics.vn', 'ngonhi@lumoralogistics.vn', NOW(), '019f2b00-0de0-7000-9300-000000000101', NOW(), '019f2b00-0de0-7000-9300-000000000101'
FROM demo_plan AS p
ON CONFLICT (id) DO UPDATE SET
